p=Path(__file__).resolve().parent/'docs/content.js'
c=json.loads(p.read_text(encoding='utf-8')[14:-1])
c['revision']='7.0'
c['scope']='Dört uygulama yolu, 120 ders, iş kararına bağlanan uygulama örnekleri ve sentetik verili vakalar.'
for lesson in c['lessons']:
    if lesson['id'] in FIELDS:
        lesson['fieldExample']=FIELDS[lesson['id']]
p.write_text('window.COURSE='+json.dumps(c,ensure_ascii=False)+';',encoding='utf-8')
